/** @param {GraphicContext} gc */
async function vizRep(gc) {
  // Shared by the card vizReps. Inlined by the generator, so it stays plain statements.
const CARD_TEXT = 0.15;
const CARD_ROW = 0.3;
// Pixels per scene unit of the text texture, high enough to stay sharp when zoomed in.
const CARD_RESOLUTION = 220;
const CARD_FONT = "Roboto, Arial, Helvetica, sans-serif";

const readValue = async (name, fallback = "") => {
  const value = await gc.expression.attrvalByName(name);
  return value === undefined || value === null || value === "" ? fallback : String(value);
};

const textCanvas = document.createElement("canvas");
const textContext = textCanvas.getContext("2d");
const useFont = (context, size) => {
  context.font = `${Math.round(size * CARD_RESOLUTION)}px ${CARD_FONT}`;
};

const textWidth = (text, size) => {
  useFont(textContext, size);
  return textContext.measureText(String(text)).width / CARD_RESOLUTION;
};

const fitText = (text, width, size) => {
  const room = width - 0.08;
  if (textWidth(text, size) <= room) return text;
  let length = text.length;
  while (length > 1 && textWidth(text.slice(0, length) + "..", size) > room) length--;
  return text.slice(0, length) + "..";
};

/**
 * Rows of cells, top to bottom, centred on the instance's position.
 *
 * Fills are cubes, because a texture's colours are not corrected on the way to the screen.
 * All text goes on one transparent plane rather than on graphic_text labels: every label
 * is a separate draggable object, so a card of a dozen would be hard to pick up, and
 * graphic_text only places a label through a stored variable per label.
 */
const drawCard = async (rows, width, outlines) => {
  const height = rows.reduce((sum, row) => sum + row.height, 0);
  // The outermost outline is a deep plate because relations find a card's edge with a ray
  // travelling almost along it, which slips past thin layers. A miss ends the relation on
  // the card's bounding sphere, and on a tall card the two ends then cross over.
  for (const [index, outline] of outlines.entries()) {
    const backPlate = index === 0;
    await gc.graphic_cube(
      width + 2 * outline.margin,
      height + 2 * outline.margin,
      backPlate ? 0.12 : 0.002,
      outline.colour,
      undefined,
      0,
      0,
      backPlate ? -0.08 : -0.018 + index * 0.003,
    );
  }

  textCanvas.width = Math.ceil(width * CARD_RESOLUTION);
  textCanvas.height = Math.ceil(height * CARD_RESOLUTION);
  textContext.textAlign = "center";
  textContext.textBaseline = "middle";
  let top = height / 2;
  for (const row of rows) {
    const y = top - row.height / 2;
    const weight = row.cells.reduce((sum, cell) => sum + (cell.weight ?? 1), 0);
    let left = -width / 2;
    for (const cell of row.cells) {
      const cellWidth = (width * (cell.weight ?? 1)) / weight;
      const centre = left + cellWidth / 2;
      await gc.graphic_cube(cellWidth - 0.015, row.height - 0.015, 0.01, cell.fill, undefined, centre, y, 0);
      if (cell.text) {
        const size = cell.size ?? CARD_TEXT;
        useFont(textContext, size);
        textContext.fillStyle = cell.colour ?? "black";
        textContext.fillText(
          fitText(cell.text, cellWidth, size),
          (centre + width / 2) * CARD_RESOLUTION,
          (height / 2 - y) * CARD_RESOLUTION,
        );
      }
      left += cellWidth;
    }
    top -= row.height;
  }
  await gc.graphic_plane(width, height, undefined, textCanvas.toDataURL("image/png"), 0, 0, 0.03);
};

  const name = await readValue('Name', 'IfcSite');
  const globalId = await readValue('IfcGloballyUniqueId');
  const rows = [
    { height: CARD_ROW, cells: [{ text: 'IfcSite', fill: '#7cb342', colour: 'black' }] },
    { height: CARD_ROW * 1.4, cells: [{ text: name, fill: '#dcedc8', size: CARD_TEXT * 1.3 }] },
    { height: CARD_ROW * 0.8, cells: [{ text: globalId, fill: '#ffffff', size: CARD_TEXT * 0.72 }] },
  ];
  const contained = (await readValue('Contained Elements')).split('\n').filter((line) => line !== '');
  for (const element of contained) {
    rows.push({ height: CARD_ROW * 0.85, cells: [{ text: element, fill: '#ffffff', size: CARD_TEXT * 0.85 }] });
  }
  const longest = Math.max(
    textWidth('IfcSite', CARD_TEXT),
    textWidth(name, CARD_TEXT * 1.3),
    textWidth(globalId, CARD_TEXT * 0.72),
    ...rows.flatMap((row) => row.cells.length === 1 ? [textWidth(row.cells[0].text ?? '', row.cells[0].size ?? CARD_TEXT)] : []),
  );
  await drawCard(rows, Math.max(2.4, longest + 0.3), [{ margin: 0.03, colour: '#222222' }]);
  let icon = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAADAAAAAwCAYAAABXAvmHAAAAa0lEQVR4nO3PMQGAQAwEwZcTHejCFSYQgQU0hBYHm3y2mOK625WZqzP8gAH/ERHZwf4B53WUZADNAJoBNANoBtAMoBlAmxPwvHdJBtAMoBlAM4BmAM0AmgE0A2gG0AygzQmobt+AjvAD4wM+3gCQJJm74PcAAAAASUVORK5CYII=';
}

