async function onProductUpdate(expression, product) {
  // IFC's 22-character GlobalId: 128 bits in base 64, with its own alphabet.
const IFC_GUID_ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz_$";
const compressUuid = (uuid) => {
  let value = BigInt("0x" + uuid.replace(/-/g, ""));
  let compressed = "";
  for (let i = 0; i < 22; i++) {
    compressed = IFC_GUID_ALPHABET[Number(value & 63n)] + compressed;
    value >>= 6n;
  }
  return compressed;
};

  const GLOBAL_ID = "0017204f-7897-5f00-82b6-104f8d4ec750";
  const CONTAINED = "09ce87fd-c7ce-57f9-b5fa-c7b7116081df";
  const NAME = "d6632c72-89fa-4210-9d01-18e911505608";
  const CHILD_RELATIONS = ["301698e6-9731-52a7-bde9-38186d9a1bc1", "1e2faabe-2c1c-558a-957b-a03791588e72"];

  const id = await expression.getAttrByInstanceUUID(product.uuid, GLOBAL_ID);
  if (id && !id.value) {
    id.value = compressUuid(product.uuid);
    await expression.checkForVisualizationUpdateByAttributeUUID(product.uuid, GLOBAL_ID);
  }

  const contained = await expression.getAttrByInstanceUUID(product.uuid, CONTAINED);
  if (!contained) return;
  const names = [];
  for (const relationClass of CHILD_RELATIONS) {
    for (const relation of await expression.getOutgoingRelationsByInstanceUUID(product.uuid, relationClass)) {
      const child = await expression.getDestinationByRelInstanceUUID(relation.uuid);
      if (child) names.push((await expression.attrvalByInst(NAME, child.uuid)) ?? child.name);
    }
  }
  const value = names.join("\n");
  if (value !== (contained.value ?? "")) {
    contained.value = value;
    await expression.checkForVisualizationUpdateByAttributeUUID(product.uuid, CONTAINED);
  }
}

